<?php
namespace App\Application\Users\Services;
use App\Domain\Contracts\Repositories\AddressRepositoryInterface;use App\Domain\Contracts\TransactionManagerInterface;use App\Domain\Models\UserAddress;
class AddressService{public function __construct(private readonly AddressRepositoryInterface $repository,private readonly TransactionManagerInterface $transactions){}public function list(string $userId):iterable{return $this->repository->listForUser($userId);}public function create(string $userId,array $data):UserAddress{return $this->transactions->run(function()use($userId,$data){if($data['is_default']??false)$this->repository->clearDefault($userId);$data['user_id']=$userId;return $this->repository->create($data);});}public function update(string $userId,string $id,array $data):UserAddress{return $this->transactions->run(function()use($userId,$id,$data){$a=$this->repository->findForUser($userId,$id);if($data['is_default']??false)$this->repository->clearDefault($userId,$id);return $this->repository->update($a,$data);});}public function delete(string $userId,string $id):void{$this->repository->delete($this->repository->findForUser($userId,$id));}}
